using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RunicOarOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/RunicOarOmenData")]
public class RunicOarOmenData : OnNewRuneOmenData
{
	[Header("Runic Oar")]
	[SerializeField]
	private int additionalPurification;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction = delegate(bool feedback)
		{
			if (feedback)
			{
				omenInstance.ActivateOmenFeedback();
			}
			return additionalPurification;
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + "\n" + Smart.Format(GetOmenRawLocalizedDescription(), additionalPurification);
	}
}
